fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    let mut result = Vec::with_capacity(x.len()); // Create a new vector with the same capacity as x
    let mut idx = 0;

    while idx < x.len() {
        result.push(x[idx]); // Push the current element to the result vector
        idx += 1; // Move to the next index
    }

    result // Return the new vector
}

fn main() {
    // Example usage
    let input_vec = vec![1.0, 2.0, 3.0];
    let length = vec_len(&input_vec);
    let output_vec = numpy_log10(input_vec.clone());

    println!("Length of input vector: {}", length);
    println!("Output vector: {:?}", output_vec);
}